    pub(in crate::game::battle::core) start: WorldVec2,
    pub(in crate::game::battle::core) aim: WorldVec2,
    pub(in crate::game::battle::core) target: Option<SkillCastTarget>,
    pub(in crate::game::battle::core) speed_units_per_ms: u32,
    pub(in crate::game::battle::core) target_unit_id: Option<UnitInstanceId>,
    pub(in crate::game::battle::core) travel_time_ms: Option<u64>,
    pub(in crate::game::battle::core) collision: SkillProjectileCollisionDef,
    pub(in crate::game::battle::core) max_kills: Option<u32>,
    pub(in crate::game::battle::core) projectile_vfx_id: Option<String>,
    pub(in crate::game::battle::core) impact_vfx_id: Option<String>,
    pub(in crate::game::battle::core) cause: BattleEventCause,
}

fn projectile_travel_ms(start: WorldVec2, aim: WorldVec2, speed_units_per_ms: u32) -> u64 {
    projectile_flight_ms_between_world_points(start, aim, speed_units_per_ms)
}

fn event_log_projectile_guidance(guidance: ProjectileGuidance) -> BattleProjectileGuidance {
    match guidance {
        ProjectileGuidance::Homing => BattleProjectileGuidance::Homing,
        ProjectileGuidance::Fixed => BattleProjectileGuidance::Fixed,
    }
}

fn facing_direction_vector(facing: FacingDirection) -> WorldVec2 {
    match facing {
        FacingDirection::Up => WorldVec2::new(0.0, -1.0),
        FacingDirection::Right => WorldVec2::new(1.0, 0.0),
        FacingDirection::Down => WorldVec2::new(0.0, 1.0),
        FacingDirection::Left => WorldVec2::new(-1.0, 0.0),
    }
}

fn directional_projectile_max_distance_world(
    speed_units_per_ms: u32,
    max_range_tiles: Option<u32>,
    max_lifetime_ms: Option<u64>,
) -> Option<f32> {
    let range_distance = max_range_tiles.map(|tiles| tiles as f32 * WORLD_UNITS_PER_TILE);
    let lifetime_distance =
        max_lifetime_ms.map(|ms| (speed_units_per_ms as f32 / DATA_UNITS_PER_WORLD) * ms as f32);

    match (range_distance, lifetime_distance) {
        (Some(range), Some(lifetime)) => Some(range.min(lifetime)),
        (Some(range), None) => Some(range),
        (None, Some(lifetime)) => Some(lifetime),
        (None, None) => None,
    }
}

fn directional_projectile_travel_ms(
    start: WorldVec2,
    aim: WorldVec2,
    speed_units_per_ms: u32,
    max_lifetime_ms: Option<u64>,
) -> u64 {
    let range_travel_ms = projectile_travel_ms(start, aim, speed_units_per_ms);
    max_lifetime_ms.map_or(range_travel_ms, |lifetime| lifetime.min(range_travel_ms))
}

fn apply_projectile_stop_policy_to_collision(
    mut collision: SkillProjectileCollisionDef,
    max_pierces: Option<u32>,
) -> SkillProjectileCollisionDef {
    let Some(max_pierces) = max_pierces else {
        return collision;
    };
    let max_hits_from_pierces = max_pierces.saturating_add(1).min(u8::MAX as u32) as u8;
    collision.max_hits = Some(match collision.max_hits {
        Some(existing) => existing.min(max_hits_from_pierces),
        None => max_hits_from_pierces,
    });
    collision
}

impl BattleCore {
    pub(in crate::game::battle::core) fn advance_skill_projectile(
        &mut self,
        time_ms: u64,
        delivery_id: Uuid,
    ) {
        if control::charge(1, "skill_projectile_advance").is_err() {
            return;
        }
        let Some(mut runtime) = self.active_projectiles.remove(&delivery_id) else {
            return;
        };

        let reevaluation_time_ms = time_ms
            .min(runtime.spawned_at_ms.saturating_add(runtime.max_travel_ms))
            .max(runtime.spawned_at_ms);

        if runtime
            .last_reevaluation_ms
            .is_some_and(|last| reevaluation_time_ms <= last)
        {
            self.active_projectiles.insert(delivery_id, runtime);
            return;
        }

        if runtime.guidance == ProjectileGuidance::Homing {
            self.advance_homing_skill_projectile_runtime(runtime, reevaluation_time_ms);
            return;
        }

        let from_elapsed_ms = runtime.last_reevaluation_ms.map_or(0, |last| {
            last.saturating_sub(runtime.spawned_at_ms).saturating_add(1)
        });
        let to_elapsed_ms = reevaluation_time_ms.saturating_sub(runtime.spawned_at_ms);
        let Ok(ProjectileMotionResult {
            end_position,
            next_reevaluation_ms,
            ordered_impacts,
        }) = self.resolve_fixed_skill_projectile_motion(&runtime, from_elapsed_ms, to_elapsed_ms)
        else {
            return;
        };
        let Ok(mut impacts) =
            Self::accept_fixed_skill_projectile_impacts(&runtime, ordered_impacts)
        else {
            return;
        };
        if runtime.max_kills.is_some() && impacts.len() > 1 {
            impacts.truncate(1);
        }

        runtime.current_position = end_position;
        runtime.last_reevaluation_ms = Some(reevaluation_time_ms);

    pub(in crate::game::battle::core) fn dispatch_skill_projectile_delivery(
        &mut self,
        time_ms: u64,
        cast_seq: u64,
        step_index: usize,
        caster_instance_id: UnitInstanceId,
        skill: &SkillDef,
        step: &SkillStepDef,
        cast_target: Option<SkillCastTarget>,
        delivery: &DeliveryDef,
        repeat_count: usize,
    ) -> usize {
        let DeliveryDef::Projectile {
            speed_units_per_ms,
            hit_policy,
            allow_targetless_cast,
            max_range_tiles,
            max_lifetime_ms,
            max_kills,
            max_pierces,
            collision,
        } = delivery
        else {
            return 0;
        };

        let mut launched_count = 0usize;
        for _ in 0..repeat_count {
            if control::charge(1, "projectile_repeat").is_err() {
                return launched_count;
            }
            let iteration_target = self.resolve_skill_step_context(
                time_ms,
                cast_seq,
                step_index,
                caster_instance_id,
                skill,
                step,
                cast_target,
            );
            if Self::skill_step_requires_hostile_usefulness(step)
                && !self.skill_step_has_useful_actual_delivery_target(
                    time_ms,
                    step_index,
                    caster_instance_id,
                    step,
                    iteration_target,
                )
            {
                continue;
            }
            let Some((caster_owner, caster_pos)) =
                self.resolve_cast_origin_context(Some(cast_seq), caster_instance_id, false)
            else {
                return launched_count;
            };
            let caster_origin = self
                .unit_world_position_or_tile_center(caster_instance_id)
                .unwrap_or_else(|| WorldVec2::from_tile_center(caster_pos));
            let Some(mut source_snapshot) = self.damage_source_snapshot_template_for_unit(
                caster_instance_id,
                DamageSource::Ability,
                DamageType::default(),
                0,
                DamageModifiers::default(),
                0,
                time_ms,
                false,
            ) else {
                continue;
            };

            source_snapshot.skill_cast_source = self
                .active_skill_casts
                .get(&cast_seq)
                .and_then(|cast| cast.execution_source.clone());
            let mut projectile_collision =
                apply_projectile_stop_policy_to_collision(*collision, *max_pierces);
            let (target_aim, guidance, target_unit_id, travel_time_ms) = match hit_policy {
                ProjectileHitPolicy::TargetLocked => {
                    let Some(SkillCastTarget::Unit { unit_instance_id }) = iteration_target else {
                        continue;
                    };
                    let Some(target_pos) = self.live_unit_projected_tile(unit_instance_id) else {
                        continue;
                    };
                    let target_aim = self
                        .unit_world_position_or_tile_center(unit_instance_id)
                        .unwrap_or_else(|| WorldVec2::from_tile_center(target_pos));
                    let travel_time_ms = projectile_flight_ms_between_world_points(
                        caster_origin,
                        target_aim,
                        *speed_units_per_ms,
                    );
                    (
                        target_aim,
                        ProjectileGuidance::Homing,
                        Some(unit_instance_id),
                        Some(travel_time_ms),
                    )
                }
                ProjectileHitPolicy::DirectionalCollision => {
                    if iteration_target.is_none() && !*allow_targetless_cast {
                        continue;
                    }
                    let Some(facing) = self
                        .units
                        .get(&caster_instance_id)
                        .and_then(|unit| unit.facing_direction)
                    else {
                        continue;
                    };
                    let Some(distance_world) = directional_projectile_max_distance_world(
                        *speed_units_per_ms,
                        *max_range_tiles,
                        *max_lifetime_ms,
                    ) else {
                        continue;
                    };
                    let direction = facing_direction_vector(facing);
                    let target_aim = caster_origin + direction * distance_world;
                    let travel_time_ms = directional_projectile_travel_ms(
                        caster_origin,
                        target_aim,
                        *speed_units_per_ms,
                        *max_lifetime_ms,
                    );
                    (
                        target_aim,
                        ProjectileGuidance::Fixed,
                        None,
                        Some(travel_time_ms),
                    )
                }
            };
            if !Self::skill_projectile_pierces(projectile_collision) && max_pierces.is_some() {
                projectile_collision.piercing = true;
            }
            let launch = SkillProjectileImpactLaunch {
                fired_at_ms: time_ms,
                cast_seq,
                step_index,
                skill_id: skill.id.clone(),
                step_id: step.id.clone(),
                caster_instance_id,
                caster_owner,
                source_snapshot,
                start: caster_origin,
                aim: target_aim,
                target: iteration_target,
                speed_units_per_ms: *speed_units_per_ms,
                target_unit_id,
                travel_time_ms,
                collision: projectile_collision,
                max_kills: *max_kills,
                projectile_vfx_id: step.presentation.projectile_vfx_id.clone(),
                impact_vfx_id: step.presentation.impact_vfx_id.clone(),
                cause: self.recording_cause().unwrap_or_default(),
            };
            match guidance {
                ProjectileGuidance::Fixed => self.spawn_fixed_skill_projectile(launch),
                ProjectileGuidance::Homing => self.spawn_homing_skill_projectile(launch),
            }
            if control::poll("projectile_spawned").is_err() {
                return launched_count;
            }
            launched_count = launched_count.saturating_add(1);
        }
        launched_count
    }

    pub(in crate::game::battle::core) fn apply_skill_projectile_impact(
        &mut self,
        time_ms: u64,
        delivery_id: Uuid,
        cast_seq: u64,
        step_index: usize,
        skill_id: SkillId,
        step_id: String,
        caster_instance_id: UnitInstanceId,
        source_snapshot: DamageSourceSnapshot,
        impact_position: WorldVec2,
        first_hit_unit_id: Option<UnitInstanceId>,
        impact_vfx_id: Option<String>,
        terminal: bool,
    ) {
        let Ok(Some(skill)) = self.cloned_skill_definition(&skill_id) else {
            return;
        };
        let Some(step) = Self::resolve_skill_step(&skill, step_index, &step_id) else {
            return;
        };

        let targets: Vec<UnitInstanceId> = first_hit_unit_id
            .filter(|unit_id| self.units.get(unit_id).is_some_and(|unit| unit.is_active()))
            .into_iter()
            .collect();

        self.update_skill_cast_impact_context(
            cast_seq,
            step_index,
            SkillImpactContext {
                delivery_id,
                impact_time_ms: time_ms,
                impact_position,
                direction_hint: None,
                first_hit_unit_id: targets.first().copied(),
                hit_unit_ids: targets.clone(),
                spawned_area_id: None,
            },
        );

        self.record_event_log(
            time_ms,
            BattleLogEvent::SkillProjectileImpacted {
                delivery_id,
                skill_id: skill_id.clone(),
                step_id: step_id.clone(),
                caster_instance_id,
                first_hit_unit_id: targets.first().copied(),
                impact_position: impact_position.quantized_milli(),
                terminal,
                impact_vfx_id,
            },
        );

        let Ok((commands, result)) = self.build_skill_step_commands(
            caster_instance_id,
            step,
            &targets,
            source_snapshot.committed_at_ms,
            Some(&source_snapshot),
        ) else {
            return;
        };
        let signal_result =
            self.record_skill_step_live_signals(caster_instance_id, &skill_id, step, &targets);
        let mut resolved_result = result;
        resolved_result.merge(&signal_result);
        let stop_outcome = if !commands.is_empty() {
            let summary = self.process_skill_commands(
                commands,
                time_ms,
                caster_instance_id,
                source_snapshot.skill_cast_source.clone(),
            );
            if control::poll("skill_commands_consumed").is_err() {
                return;
            }
            resolved_result.actual_damage_target_count = resolved_result
                .actual_damage_target_count
                .saturating_add(summary.actual_damage_target_count);
            self.apply_skill_projectile_kill_stop_policy(delivery_id, summary.killed_target_count)
        } else {
            SkillProjectileStopOutcome::Continue
        };
        self.resolve_skill_step_delivery(
            cast_seq,
            step_index,
            resolved_result,
            terminal || stop_outcome.is_terminal(),
            time_ms,
        );
        self.schedule_pending_autocasts(time_ms);
    }
}

pub(in crate::game::battle::core) fn register_persistent_tile_area(
    &mut self,
    time_ms: u64,
    cast_seq: u64,
    step_index: usize,
    caster_instance_id: UnitInstanceId,
    skill_id: SkillId,
    step_id: String,
    step: &SkillStepDef,
    step_target: Option<SkillCastTarget>,
    tile_range: TileRangePattern,
    area: SkillTileAreaDeliveryDef,
) -> bool {
    area.validate_runtime_contract();
    let Some((_caster_owner, origin, center, direction_hint, anchor_tile)) = self
        .resolve_tile_area_geometry(
            time_ms,
            cast_seq,
            step_index,
            caster_instance_id,
            step_target,
            &area,
        )
    else {
        return false;
    };
    let Some(facing) = self.tile_area_projection_facing(caster_instance_id, &tile_range) else {
        return false;
    };
    let Some(mut source_snapshot) = self.damage_source_snapshot_template_for_unit(
        caster_instance_id,
        DamageSource::Ability,
        DamageType::default(),
        0,
        DamageModifiers::default(),
        0,
        time_ms,
        false,
    ) else {
        return false;
    };
    source_snapshot.skill_cast_source = self
        .active_skill_casts
        .get(&cast_seq)
        .and_then(|cast| cast.execution_source.clone());
    let Some(affected_tiles) = self.valid_tile_area_tiles(&tile_range, anchor_tile, facing)
    else {
        return false;
    };
    let targets = self.collect_tile_area_targets_at(
        time_ms,
        _caster_owner,
        caster_instance_id,
        &affected_tiles,
        area.hit_targets,
        area.include_caster,
    );
    if self.skill_step_needs_hostile_usefulness_gate(
        caster_instance_id,
        step,
        area.hit_targets,
        &targets,
    ) && !self.skill_step_has_useful_hostile_target(caster_instance_id, step, &targets)
    {
        return false;
    }

    if self
        .admit_authoring_runtime_growth(2, "persistent_area_spawn")
        .is_err()
    {
        return false;
    }
    let area_id = self.allocate_area_instance_id(cast_seq, caster_instance_id, time_ms);
    let area_declared_seq = self.record_skill_tile_area_declared(
        time_ms,
        area_id,
        skill_id.clone(),
        step_id.clone(),
        caster_instance_id,
        step_target,
        origin,
        center,
        direction_hint,
        affected_tiles,
        area.clone(),
    );
    let expires_at_ms = time_ms.saturating_add(u64::from(area.duration_ms));
    let next_tick_ms = area
        .tick_interval_ms
        .map(|interval| time_ms.saturating_add(u64::from(interval)));
    self.active_areas.insert(
        area_id,
        AreaRuntime {
            area_id,
            cast_seq,
            step_index,
            skill_id: skill_id.clone(),
            step_id: step_id.clone(),
            caster_instance_id,
            caster_owner: _caster_owner,
            source_snapshot,
            anchor: area.anchor,
            tile_origin: area.tile_origin,
            tracking: area.tracking,
            origin,
            center,
            direction_hint,
            facing,
            tile_range,
            tile_anchor: anchor_tile,
            hit_targets: area.hit_targets,
            include_caster: area.include_caster,
            tick_policy: area.tick_policy,
            duration_ms: area.duration_ms,

pub(in crate::game::battle::core) fn apply_skill_area_tick(
    &mut self,
    time_ms: u64,
    area_id: Uuid,
) {
    let Some(runtime) = self.active_areas.get(&area_id) else {
        return;
    };
    if Self::charge_authoring_tile_pattern(&runtime.tile_range, 1).is_err()
        || control::charge(
            runtime.hit_unit_ids.len() as u64 + runtime.previous_tick_unit_ids.len() as u64 + 1,
            "area_runtime_copy",
        )
        .is_err()
        || self
            .admit_authoring_runtime_growth(0, "area_tick_state")
            .is_err()
    {
        return;
    }
    let runtime = runtime.clone();

    let Some((origin, center, direction_hint, anchor_tile)) =
        self.persistent_tile_area_geometry_at(time_ms, &runtime)
    else {
        return;
    };
    let facing = match runtime.tracking {
        SkillAreaTracking::GroundFixed => runtime.facing,
        SkillAreaTracking::FollowCaster | SkillAreaTracking::FollowTarget => {
            let Some(facing) = self
                .tile_area_projection_facing(runtime.caster_instance_id, &runtime.tile_range)
            else {
                return;
            };
            facing
        }
    };
    let Some(affected_tiles) =
        self.valid_tile_area_tiles(&runtime.tile_range, anchor_tile, facing)
    else {
        return;
    };
    let raw_targets = self.collect_tile_area_targets_at(
        time_ms,
        runtime.caster_owner,
        runtime.caster_instance_id,
        &affected_tiles,
        runtime.hit_targets,
        runtime.include_caster,
    );
    let history = match runtime.tick_policy {
        SkillAreaTickPolicy::EveryTick => 0,
        SkillAreaTickPolicy::OncePerArea => runtime.hit_unit_ids.len(),
        SkillAreaTickPolicy::OnEnter => runtime.previous_tick_unit_ids.len(),
    };
    if control::charge(
        (raw_targets.len() as u64).saturating_mul(history as u64 + 1),
        "area_tick_policy_scan",
    )
    .is_err()
    {
        return;
    }
    let targets: Vec<UnitInstanceId> = match runtime.tick_policy {
        SkillAreaTickPolicy::EveryTick => raw_targets.clone(),
        SkillAreaTickPolicy::OncePerArea => raw_targets
            .iter()
            .copied()
            .filter(|target_id| !runtime.hit_unit_ids.contains(target_id))
            .collect(),
        SkillAreaTickPolicy::OnEnter => raw_targets
            .iter()
            .copied()
            .filter(|target_id| !runtime.previous_tick_unit_ids.contains(target_id))
            .collect(),
    };

    let Ok(Some(skill)) = self.cloned_skill_definition(&runtime.skill_id) else {
        return;
    };
    let Some(step) = Self::resolve_skill_step(&skill, runtime.step_index, &runtime.step_id)
    else {
        return;
    };
    let source_snapshot = self.area_tick_source_snapshot(&runtime, time_ms);
    let Ok((commands, result)) = self.build_skill_step_commands(
        runtime.caster_instance_id,
        step,
        &targets,
        time_ms,
        Some(&source_snapshot),
    ) else {
        return;
    };
    let mut resolved_result = result;
    if !commands.is_empty() {
        let summary = self.process_skill_commands(
            commands,
            time_ms,
            runtime.caster_instance_id,
            source_snapshot.skill_cast_source.clone(),
        );
        if control::poll("skill_commands_consumed").is_err() {
            return;
        }
        resolved_result.actual_damage_target_count = resolved_result
            .actual_damage_target_count
            .saturating_add(summary.actual_damage_target_count);
    }
    let signal_result = self.record_skill_step_live_signals(
        runtime.caster_instance_id,
        &skill.id,
        step,
        &targets,
    );
    resolved_result.merge(&signal_result);
    self.update_skill_cast_impact_context(
        runtime.cast_seq,
        runtime.step_index,
        SkillImpactContext {
            delivery_id: runtime.area_id,
            impact_time_ms: time_ms,
            impact_position: center,
            direction_hint: Some(direction_hint),
            first_hit_unit_id: targets.first().copied(),
            hit_unit_ids: targets.clone(),
            spawned_area_id: Some(runtime.area_id),
        },
    );
    self.resolve_skill_step_delivery(
        runtime.cast_seq,
        runtime.step_index,
        resolved_result,
        false,
        time_ms,
    );

    if control::poll("area_step_resolved").is_err() {
        return;
    }
    if let Some(active) = self.active_areas.get(&area_id) {
        let change = match active.tick_policy {
            SkillAreaTickPolicy::EveryTick => (0, 0),

            }
        }
        self.schedule_pending_autocasts(time_ms);
    }

    pub(in crate::game::battle::core) fn expire_skill_area(&mut self, area_id: Uuid) {
        let Some(runtime) = self.active_areas.remove(&area_id) else {
            return;
        };
        if let Some(cast) = self.active_skill_casts.get_mut(&runtime.cast_seq) {
            cast.active_area_ids.retain(|id| *id != area_id);
        }
        self.resolve_skill_step_delivery(
            runtime.cast_seq,
            runtime.step_index,
            SkillStepResult::default(),
            true,
            runtime.expires_at_ms,
        );
    }
}

