fn hit_gated_self_heal_and_buff_stack_repeat_attack_work_together() {
    let caster_base_uuid = Uuid::from_u128(0xBD11);
    let enemy_base_uuid = Uuid::from_u128(0xBD12);

    let skill = SkillDef {
        id: SkillId::from("predation_cycle"),
        name: "predation_cycle".to_string(),
        kind: SkillKind::Targeted,
        cast_targeting: explicit_cast_targeting(SkillTarget::SelfUnit),
        focus_time_ms: 100,
        focus_permissions: Default::default(),
        steps: vec![
            SkillStepDef {
                id: "prime_stacks".to_string(),
                delay_ms: 0,
                target: SkillTarget::SelfUnit,
                targeting: StepTargetingMode::ReuseCastTarget,
                when: SkillStepCondition::Always,
                repeat: SkillStepRepeat::Times { count: 3 },
                delivery: DeliveryDef::Instant,
                effects: vec![
                    SkillEffectDef::ApplyBuff {
                        buff_id: "poison".to_string(),
                        duration_ms: 5_000,
                    }
                    .authored("effect_01"),
                    SkillEffectDef::Damage {
                        amount: 5,
                        damage_type: game_core::game::battle::damage::DamageType::Magic,
                    }
                    .authored("effect_02"),
                ],
                presentation: SkillPresentationDef::default(),
            },
            SkillStepDef {
                id: "opening_strike".to_string(),
                delay_ms: 1,
                target: SkillTarget::EnemySingle {
                    rule: UnitTargetRule::Nearest,
                },
                targeting: StepTargetingMode::RetargetOnStep,
                when: SkillStepCondition::Always,
                repeat: SkillStepRepeat::Once,
                delivery: DeliveryDef::Instant,
                effects: vec![SkillEffectDef::Damage {
                    amount: 12,
                    damage_type: game_core::game::battle::damage::DamageType::Magic,
                }
                .authored("effect_01")],
                presentation: SkillPresentationDef::default(),
            },
            SkillStepDef {
                id: "heal_on_hit".to_string(),
                delay_ms: 2,
                target: SkillTarget::SelfUnit,
                targeting: StepTargetingMode::ReuseCastTarget,
                when: SkillStepCondition::IfPreviousStepDealtDamage,
                repeat: SkillStepRepeat::Once,
                delivery: DeliveryDef::Instant,
                effects: vec![SkillEffectDef::Heal { amount: 8 }.authored("effect_01")],
                presentation: SkillPresentationDef::default(),
            },
            SkillStepDef {
                id: "stacked_barrage".to_string(),
                delay_ms: 3,
                target: SkillTarget::EnemySingle {
                    rule: UnitTargetRule::Nearest,
                },
                targeting: StepTargetingMode::RetargetOnStep,
                when: SkillStepCondition::Always,
                repeat: SkillStepRepeat::ByBuffStacks {
                    unit: SkillUnitReference::SelfUnit,
                    buff_id: "poison".to_string(),
                    max: Some(5),
                },
                delivery: DeliveryDef::Instant,
                effects: vec![SkillEffectDef::Damage {
                    amount: 7,
                    damage_type: game_core::game::battle::damage::DamageType::Magic,
                }
                .authored("effect_01")],
                presentation: SkillPresentationDef::default(),
            },
        ],
    };

    let game_data = minimal_game_data(
        vec![
            make_abnormality(
                "caster",
                caster_base_uuid,
                Some("predation_cycle"),
                1,
                120,
                0,
                300,
                DeliveryDef::Instant,
                10,
            ),
            make_abnormality(
                "enemy",
                enemy_base_uuid,
                None,
                1,
                500,
                9999,
                1_000_000,
                DeliveryDef::Instant,
                100,
            ),
        ],
        vec![skill],
    );

    let event_log = run_battle(
        game_data,
        vec![(Uuid::from_u128(31), caster_base_uuid, Position::new(0, 0))],
        vec![(Uuid::from_u128(32), enemy_base_uuid, Position::new(0, 1))],
    );

    let caster_id = spawned_unit_id(&event_log, caster_base_uuid, Side::Player);
    let enemy_id = spawned_unit_id(&event_log, enemy_base_uuid, Side::Opponent);
    let (ability_seq, _) = find_first_ability_cast_seq(&event_log, "predation_cycle", caster_id);
    let steps = step_entries_for_cast(&event_log, ability_seq);
    assert_eq!(steps.len(), 4, "expected all 4 steps to execute");

    let heal_step = steps[2];
    let barrage_step = steps[3];

    let heal_events = event_log
        .entries
        .iter()
        .filter(|entry| {
            matches!(
                &entry.event,
                BattleLogEvent::HpChanged {
                    source_instance_id: Some(source_instance_id),
                    target_instance_id,
                    reason,
                    hp_after,
                    hp_before,
                    ..
                } if *source_instance_id == caster_id.into()
                    && *target_instance_id == caster_id.into()
                    && *reason == HpChangeReason::Command
                    && hp_after > hp_before
            ) && entry_caused_by_seq(&event_log, entry, heal_step.seq)
        })
        .count();
    assert_eq!(
        heal_events, 1,
        "expected a single self-heal after the opening hit"
    );

    let barrage_hits = event_log
        .entries
        .iter()
        .filter(|entry| {
            matches!(
                &entry.event,
                BattleLogEvent::HpChanged {
                    source_instance_id: Some(source_instance_id),
                    target_instance_id,
                    reason,
                    ..
                } if *source_instance_id == caster_id.into()
                    && *target_instance_id == enemy_id.into()
                    && *reason == HpChangeReason::Command
            ) && entry_caused_by_seq(&event_log, entry, barrage_step.seq)
        })
        .count();
    assert_eq!(
        barrage_hits, 3,
        "expected repeated barrage hits to match the caster's 3 poison stacks"
    );
}

fn committed_damage_uses_actual_overkill_delta_and_finalizes_one_causal_death() {
    let attacker_id = crate::game::battle::ids::UnitInstanceId::from(Uuid::from_u128(0xC283));
    let target_id = crate::game::battle::ids::UnitInstanceId::from(Uuid::from_u128(0xC284));

    for delivery in [AttackDelivery::Instant, AttackDelivery::Projectile] {
        let mut core = committed_damage_test_core(attacker_id, target_id, delivery, 5);
        let snapshot = core
            .damage_source_snapshot_for_unit(
                attacker_id,
                target_id,
                DamageSource::BasicAttack,
                DamageType::Physical,
                100,
                DamageModifiers::default(),
                1,
                0,
                true,
            )
            .expect("basic source snapshot");
        assert!(core.resolve_committed_basic_attack(
            attacker_id,
            target_id,
            snapshot,
            delivery,
            0,
        ));
        if matches!(delivery, AttackDelivery::Projectile) {
            let projectile_id = *core
                .projectiles
                .keys()
                .next()
                .expect("launched basic projectile");
            core.advance_basic_attack_projectile(1, projectile_id);
        }

        assert_eq!(damage_observation(&core, target_id).2, -5);
        assert_eq!(core.units[&attacker_id].resonance_current, 10);
        assert!(core.graveyard.contains_key(&target_id));
        assert_eq!(
            core.event_log
                .entries
                .iter()
                .filter(|entry| matches!(
                    entry.event,
                    BattleLogEvent::UnitDied { unit_instance_id, .. }
                        if unit_instance_id == target_id
                ))
                .count(),
            1
        );
    }

    let mut general =
        committed_damage_test_core(attacker_id, target_id, AttackDelivery::Instant, 5);
    let snapshot = general
        .damage_source_snapshot_for_unit(
            attacker_id,
            target_id,
            DamageSource::Ability,
            DamageType::Physical,
            100,
            DamageModifiers::default(),
            0,
            0,
            false,
        )
        .expect("general source snapshot");
    let parent_seq = general.record_event_log(
        0,
        BattleLogEvent::BattleStart {
            width: 4,
            height: 4,
        },
    );
    let summary = general.with_recording_cause(parent_seq, |core| {
        core.process_commands(
            vec![BattleCommand::ApplyDamage {
                target_id,
                source_snapshot: snapshot,
            }],
            1,
        )
    });
    assert_eq!(summary.actual_damage_target_count, 1);
    assert_eq!(summary.killed_target_count, 1);

    let damage_entries: Vec<_> = general
        .event_log
        .entries
        .iter()
        .filter(|entry| {
            matches!(
                entry.event,
                BattleLogEvent::HpChanged { target_instance_id, .. }
                    | BattleLogEvent::UnitDied {
                        unit_instance_id: target_instance_id,
                        ..
                    } if target_instance_id == target_id
            )
        })
        .collect();
    assert_eq!(damage_entries.len(), 2);
    assert!(matches!(
        damage_entries[0].event,
        BattleLogEvent::HpChanged { delta: -5, .. }
    ));
    assert!(matches!(
        damage_entries[1].event,
        BattleLogEvent::UnitDied {
            killer_instance_id: Some(killer_id),
            ..
        } if killer_id == attacker_id
    ));
    assert!(damage_entries
        .iter()
        .all(|entry| entry.cause == BattleEventCause::Parent { seq: parent_seq }));
}

