}

fn path_index(path: &str, name: &str) -> Option<usize> {
    let (_, tail) = path.split_once(&format!("{name}["))?;
    tail.split_once(']')?.0.parse().ok()
}

// Best-effort identities for syntactically readable but unsupported op/property
// input. This second parse is diagnostic-only and can never publish game data.
fn enrich_parse_error(
    input: &str,
    mut error: super::live_ron::LiveRonError,
) -> super::live_ron::LiveRonError {
    #[derive(Deserialize)]
    #[serde(rename = "SkillDatabase")]
    struct Locations {
        skills: Vec<Definition>,
    }
    #[derive(Deserialize)]
    #[serde(rename = "SkillDef")]
    struct Definition {
        #[serde(default)]
        id: String,
        #[serde(default)]
        steps: Vec<Action>,
    }
    #[derive(Deserialize)]
    #[serde(rename = "SkillStepDef")]
    struct Action {
        #[serde(default)]
        id: String,
        #[serde(default)]
        effects: Vec<Effect>,
    }
    #[derive(Deserialize)]
    struct Effect {
        #[serde(default)]
        id: String,
    }
    if let (Ok(locations), Some(path)) = (
        ron::de::from_str::<Locations>(input),
        error.field_path.as_deref(),
    ) {
        if let Some(definition) = path_index(path, "skills").and_then(|i| locations.skills.get(i)) {
            error.object_id = (!definition.id.is_empty()).then(|| definition.id.clone());
            if let Some(action) = path_index(path, "steps").and_then(|i| definition.steps.get(i)) {
                error.action_id = (!action.id.is_empty()).then(|| action.id.clone());
                error.effect_id = path_index(path, "effects")
                    .and_then(|i| action.effects.get(i))
                    .filter(|effect| !effect.id.is_empty())
                    .map(|effect| effect.id.clone());
            }
        }
    }
    error
}

