BattleEvent::BuffTick {
    time_ms,
    caster_instance_id,
    target_instance_id,
    buff_id,
    cause,
} => {
    let Some(def) = self
        .game_data
        .buff_data
        .get(buff_id)
        .map(crate::authoring::clone_shape::controlled_clone)
        .transpose()?
    else {
        return Ok(());
    };

    let key = BuffInstanceKey {
        caster_instance_id,
        target_instance_id,
        buff_id,
    };

    let Some(active) = self.buffs.get(&key) else {
        return Ok(());
    };

    if Some(time_ms) != active.next_tick_ms {
        return Ok(());
    }

    let (stacks, expires_at_ms) = (active.stacks, active.expires_at_ms);

    let tick_seq = self.with_recording_context(cause, |core| {
        core.record_event_log(
            time_ms,
            BattleLogEvent::BuffTick {
                caster_instance_id,
                target_instance_id,
                buff_id,
            },
        )
    });

    if let crate::game::battle::buffs::BuffKind::PeriodicDamage {
        damage_per_tick,
        damage_type,
    } = def.kind
    {
        let stacks = stacks.max(1) as i32;
        let dmg = (damage_per_tick as i32).saturating_mul(stacks);
        if dmg > 0 {
            self.with_recording_cause(tick_seq, |core| {
                let Some(source_snapshot) = core.damage_source_snapshot_for_unit(
                    caster_instance_id,
                    target_instance_id,
                    DamageSource::BuffTick,
                    damage_type,
                    dmg as u32,
                    Default::default(),
                    0,
                    time_ms,
                    false,
                ) else {
                    return;
                };
                core.process_commands(
                    vec![BattleCommand::ApplyDamage {
                        target_id: target_instance_id,
                        source_snapshot,
                    }],
                    time_ms,
                );
                core.schedule_pending_autocasts(time_ms);
            });
        }
    }

    let next_tick_ms = time_ms.saturating_add(def.tick_interval_ms);
    if let Some(active) = self.buffs.get_mut(&key) {
        if next_tick_ms < expires_at_ms {
            active.next_tick_ms = Some(next_tick_ms);
            self.event_queue.push(BattleEvent::BuffTick {
                time_ms: next_tick_ms,
                caster_instance_id,
                target_instance_id,
                buff_id,
                cause,
            });
        } else {
            active.next_tick_ms = None;
        }
    }

    Ok(())
}
BattleEvent::BuffExpire {
    time_ms,
    caster_instance_id,
    target_instance_id,
    buff_id,

    fn apply_basic_attack_projectile_hit_at(
        &mut self,
        time_ms: u64,
        projectile_id: Uuid,
        attacker_instance_id: UnitInstanceId,
        target_instance_id: UnitInstanceId,
        source_snapshot: DamageSourceSnapshot,
        impact_position: WorldVec2,
    ) {
        {
            let Some(target) = self.units.get(&target_instance_id) else {
                self.record_basic_attack_projectile_miss(
                    time_ms,
                    projectile_id,
                    attacker_instance_id,
                    target_instance_id,
                    source_snapshot.damage_type,
                    impact_position,
                );
                return;
            };
            if !target.is_active() {
                self.record_basic_attack_projectile_miss(
                    time_ms,
                    projectile_id,
                    attacker_instance_id,
                    target_instance_id,
                    source_snapshot.damage_type,
                    impact_position,
                );
                return;
            }
        }

        self.record_event_log(
            time_ms,
            BattleLogEvent::BasicAttackProjectileImpacted {
                projectile_id,
                attacker_instance_id,
                target_instance_id,
                impact_position: impact_position.quantized_milli(),
                hit: true,
            },
        );

        let _ = self.execute_committed_damage(CommittedDamageInput {
            target_id: target_instance_id,
            source_snapshot,
            committed_at_ms: time_ms,
            policy: CommittedDamagePolicy::BasicAttack {
                occurrence_id: projectile_id,
                occurrence_time_ms: time_ms,
            },
        });

        self.schedule_pending_autocasts(time_ms);
    }
}

pub(in crate::game::battle::core) fn deploy_player_unit(
    &mut self,
    draft: BattleUnitDraft,
    position: Position,
    tile_kind: TacticalTileKind,
    facing: crate::game::battle::tile_range::FacingDirection,
    instance_salt: u32,
    time_ms: u64,
    current_hp_policy: Option<super::sim::BattleDeployCurrentHpPolicy>,
) -> Result<UnitInstanceId, GameError> {
    self.validate_player_tactical_destination(position, None)?;
    self.validate_field_work_cell_destination(position, tile_kind)?;
    let employee_uuid = draft.owned_uuid;
    let weapon_profile = draft
        .combat_profile(&self.game_data)?
        .weapon_profile
        .ok_or(GameError::WeaponRequired)?;
    let group_id = ScenarioGroupId::new(format!("live_player_deploy_{instance_salt}"));
    let unit_ref = ScenarioUnitRef::new(format!("{}_0", group_id.0));
    self.scenario.groups.push(ScenarioSpawnGroup {
        id: group_id.clone(),
        side: Side::Player,
        required_for_victory: false,
        enemy_movement_plan: None,
        spawns: vec![ScenarioUnitSpawn {
            unit_ref,
            side: Side::Player,
            draft,
            position,
            instance_salt,
        }],
    });

    let spawned_unit_ids = self.spawn_scenario_group(&group_id)?;
    let unit_id = spawned_unit_ids
        .first()
        .copied()
        .ok_or(GameError::InvalidAction)?;
    if let Some(unit) = self.units.get_mut(&unit_id) {
        unit.facing_direction = Some(facing);
        if let Some(current_hp_policy) = current_hp_policy {
            unit.stats.current_health =
                current_hp_policy.current_hp_for_max(unit.stats.max_health);
        }
    }
    self.initialize_deployed_tactical_state(unit_id, tile_kind, weapon_profile, time_ms)?;
    let actual_position = self
        .unit_projected_tile(unit_id)
        .ok_or(GameError::InvalidAction)?;
    self.record_spawned_units(
        time_ms,
        BattleEventCause::Root {
            kind: BattleEventRootCause::System,
        },
        &spawned_unit_ids,
    )?;
    self.record_event_log(
        time_ms,
        BattleLogEvent::UnitDeployed {

        Self {
            stats: BattleResultEmployeeStatsDto {
                employee_uuid,
                unit_instance_id,
                survived: false,
                became_incapacitated: false,
                final_hp: 0,
                max_hp: 0,
                damage_dealt: 0,
                damage_taken: 0,
                kill_count: 0,
                basic_attack_count: 0,
                skill_cast_count: 0,
                deployed_count: 0,
                withdrawn_count: 0,
                deployed_time_ms: 0,
            },
        }
    }
}

